<script>document.addEventListener('DOMContentLoaded',()=>{const kind=document.getElementById('movement-kind'),direction=document.getElementById('adjustment-direction'),directionSelect=document.getElementById('adjustment-direction-select'),destination=document.getElementById('destination-warehouse'),costField=document.getElementById('unit-cost-field'),cost=document.getElementById('unit-cost');const toggle=()=>{const adjustment=kind?.value==='adjustment',transfer=kind?.value==='transfer',requiresCost=kind?.value==='receipt'||(adjustment&&directionSelect?.value==='increase');direction?.classList.toggle('d-none',!adjustment);destination?.classList.toggle('d-none',!transfer);costField?.classList.toggle('d-none',!requiresCost);if(cost)cost.required=requiresCost;};kind?.addEventListener('change',toggle);directionSelect?.addEventListener('change',toggle);toggle();document.querySelectorAll('.reverse-stock').forEach(button=>button.addEventListener('click',()=>{document.getElementById('reverse-form').action=button.dataset.action;document.getElementById('reverse-document').textContent=button.dataset.number;}));});</script>
